// Types for the precomputed historical data in /data/hist/ (generated by scripts/cricsheet/build.mjs
// from Cricsheet ball-by-ball data, ODC-BY 1.0). Also exports the exact feature functions used in
// training so the client computes identical model inputs.

export type HistFormat = 'T20' | 'ODI' | 'Test'
export type Phase = 'pp' | 'mid' | 'death'
export type WktBucket = '0-2' | '3-5' | '6-7' | '8-9'
export type BallOutcome = '0' | '1' | '2' | '3' | '4' | '6' | 'W' | 'wd' | 'nb' | 'lb'
export type MatchResult = 'win' | 'tie' | 'draw' | 'nr'

// ---------------------------------------------------------------------------------------------
// model.json
// ---------------------------------------------------------------------------------------------
export interface EvalScores { n: number; logLoss: number; brier: number }

export interface ModelEval {
  trainRows: number
  testRows: number
  trainMatches: number
  testMatches: number
  /** e.g. "train < 2023-01-01, test >= 2023-01-01" */
  split: string
  train: EvalScores
  test: EvalScores | null
  /** constant-probability baseline (train base rate) on the test set */
  baselineTest: { logLoss: number; brier: number } | null
}

/** p = sigmoid(intercept + sum_i coef[i] * (x[i] - mean[i]) / std[i]) */
export interface LogisticModel<F extends string = string> {
  features: F[]
  mean: number[]
  std: number[]
  coef: number[]
  intercept: number
  eval: ModelEval
}

export type ChaseFeature =
  | 'rrr' | 'crr' | 'wkts_in_hand' | 'balls_left_frac' | 'runs_needed_frac'
  | 'rrr_x_balls_left_frac' | 'wkts_in_hand_x_balls_left_frac' | 'log_runs_needed_per_wkt'
export type FirstFeature =
  | 'runs' | 'wkts_lost' | 'balls_left_frac' | 'crr' | 'venue_par_diff' | 'wkts_lost_x_balls_left_frac'

export interface FirstInningsModel extends LogisticModel<FirstFeature> {
  /** Global par (avg cumulative 1st-innings score after k overs, k = 0..N) from training years; fallback when venue par unavailable */
  parGlobal: number[]
  /** Venue par is used only if the venue has at least this many full-length first innings (VenueFormatBlock.parN) */
  venueParMinMatches: number
}

export type OutcomeProbs = Record<BallOutcome, number> & { /** sample size */ n: number }

export interface OutcomeTables {
  /** first season of data used */
  since: number
  /** inclusive 1-based over ranges per phase */
  phases: Record<Phase, [number, number]>
  tables: Record<Phase, Partial<Record<WktBucket, OutcomeProbs>>>
  /** mean total runs on a wide / no-ball / bye-or-legbye delivery (incl. the extra itself) */
  extraRuns: { wd: number; nb: number; lb: number }
}

export interface ExpectedRunsTable {
  ballsStep: 6
  rows: string
  cols: string
  /** table[ballsLeft / 6][wktsLost] = expected remaining runs (wktsLost 0..9); monotone in both axes */
  table: number[][]
  /** raw observation counts per cell */
  n: number[][]
}

export interface FormatModel {
  format: 'T20' | 'ODI'
  gender: 'male' | 'female'
  /** avg cumulative 1st-innings score after k overs (k = 0..20 / 0..50), full-length innings 2016+ */
  par: number[]
  chase: LogisticModel<ChaseFeature>
  first: FirstInningsModel
  outcomes: OutcomeTables
  expected: ExpectedRunsTable
}

export interface HistModelFile {
  generatedAt: string
  trainCutoff: string
  notes: string
  T20?: FormatModel
  ODI?: FormatModel
  T20_women?: FormatModel
  ODI_women?: FormatModel
}

// ---------------------------------------------------------------------------------------------
// venues.json
// ---------------------------------------------------------------------------------------------
/** Men's formats use T20/ODI/Test; women's use T20W/ODIW/TestW. */
export type VenueFormatKey = 'T20' | 'ODI' | 'Test' | 'T20W' | 'ODIW' | 'TestW'

export interface InningsRecord { score: number; wkts: number; team: string; date: string }

export interface VenueRecentResult {
  date: string
  teams: [string, string]
  result: MatchResult
  winner: string | null
  margin?: string
}

export interface VenueFormatBlock {
  matches: number
  avg1st?: number
  avg2nd?: number
  /** % of decided matches won by the side batting second (Tests: % of non-abandoned matches, draws in denominator) */
  chaseWinPct?: number
  batFirstWinPct?: number
  tossWinMatchWinPct?: number
  tossBatFirstPct?: number
  highest?: InningsRecord
  lowest?: InningsRecord
  /** limited overs only: avg cumulative 1st-innings score after k overs (index 0..N) */
  parByOver?: number[]
  /** number of full-length first innings behind parByOver */
  parN?: number
  avgPowerplay?: number
  avgDeath?: number
  wicketsByKind: Record<string, number>
  /** Tests only */
  drawPct?: number
  /** last 5 results, newest first */
  recent: VenueRecentResult[]
}

export interface HistVenue {
  name: string
  city?: string
  formats: Partial<Record<VenueFormatKey, VenueFormatBlock>>
}

export interface HistVenuesFile {
  venues: Record<string, HistVenue>
  /** alternate normalised key -> canonical key */
  venueAliases: Record<string, string>
  /** generic ground names that are keyed as "<base> <cityKey>" (e.g. "county ground taunton") */
  ambiguousBaseKeys: string[]
  /** city normalisation applied before building "<base> <cityKey>" */
  cityAliases: Record<string, string>
}

// ---------------------------------------------------------------------------------------------
// players/{shard}.json   (shard = Number(cricinfoId) % 128)
// ---------------------------------------------------------------------------------------------
export type PlayerFormatKey = 'T20' | 'T20I' | 'ODI' | 'ODI_intl' | 'Test' | 'Test_intl'

export interface BatPhase { runs: number; balls: number; outs: number }
export interface BowlPhase { balls: number; runs: number; wkts: number }

export interface BattingStats {
  inns: number
  runs: number
  balls: number
  outs: number
  notOuts: number
  fours: number
  sixes: number
  hs: number
  hsNotOut: boolean
  fifties: number
  hundreds: number
  ducks: number
  avg: number | null
  sr: number | null
  phases?: Partial<Record<Phase, BatPhase>>
}

export interface BowlingStats {
  inns: number
  balls: number
  runs: number
  wkts: number
  dots: number
  fours: number
  sixes: number
  wides: number
  noballs: number
  econ: number | null
  avg: number | null
  sr: number | null
  best: { w: number; r: number }
  /** innings with exactly 4 wickets */
  fourW: number
  /** innings with 5+ wickets */
  fiveW: number
  /** bowler-credited dismissals by kind: bowled, caught, lbw, stumped, 'caught and bowled', 'hit wicket' */
  dismissals?: Record<string, number>
  phases?: Partial<Record<Phase, BowlPhase>>
}

export interface FieldingStats { catches: number; stumpings: number; runOuts: number }

export interface PlayerFormatStats {
  matches: number
  bat?: BattingStats
  bowl?: BowlingStats
  field?: FieldingStats
}

export interface PlayerRecentEntry {
  d: string
  f: HistFormat
  ev?: string
  opp: string
  v: string
  r?: number
  b?: number
  out?: boolean
  /** number of batting innings in the match when > 1 (Tests); r/b are summed, out refers to the last innings */
  inns?: number
  w?: number
  rc?: number
  bb?: number
}

/** [balls, runs, outs, dots, fours, sixes] */
export type Matchup = [number, number, number, number, number, number]

export interface HistPlayer {
  name: string
  formats: Partial<Record<PlayerFormatKey, PlayerFormatStats>>
  /** last 15 matches batted or bowled in, newest first */
  recent: PlayerRecentEntry[]
  /** as batter, keyed by bowler cricinfo id (2015+, >= 6 balls) */
  vs: Record<string, Matchup>
  /** as bowler, keyed by batter cricinfo id (2015+, >= 6 balls) */
  vb: Record<string, Matchup>
}

export type HistPlayerShard = Record<string, HistPlayer>

// ---------------------------------------------------------------------------------------------
// h2h.json / teams.json
// ---------------------------------------------------------------------------------------------
export interface H2HResult {
  d: string
  winner: string | null
  /** present when not a win */
  result?: 'tie' | 'draw' | 'nr'
  margin?: string
  venue: string
  ev?: string
}

export interface H2HFormatBlock {
  matches: number
  /** keyed by both team names */
  wins: Record<string, number>
  ties: number
  noResult: number
  draws: number
  /** last 6, newest first */
  last: H2HResult[]
}

export interface HistH2HFile {
  /** franchise renames old -> current (already merged) */
  aliases: Record<string, string>
  /** key "TeamA|TeamB" with names sorted alphabetically (women's sides suffixed " Women") */
  pairs: Record<string, Partial<Record<HistFormat, H2HFormatBlock>>>
}

export interface TeamRecentResult {
  d: string
  f: HistFormat
  opp: string
  result: 'W' | 'L' | 'T' | 'NR' | 'D'
  margin?: string
  ev?: string
  v: string
}

export interface TeamFormatRecord { played: number; won: number; lost: number; tied: number; noResult: number; drawn: number }

export interface HistTeam {
  /** last 10, newest first */
  recent: TeamRecentResult[]
  /** since `formsSince` (3 years before the latest match in the data) */
  formats: Partial<Record<HistFormat, TeamFormatRecord>>
}

export interface HistTeamsFile {
  aliases: Record<string, string>
  formsSince: string
  teams: Record<string, HistTeam>
}

// ---------------------------------------------------------------------------------------------
// meta.json
// ---------------------------------------------------------------------------------------------
export interface HistMetaFile {
  generatedAt: string
  source: string
  attribution: string
  license: string
  matches: number
  latestMatchDate: string
  players: number
  venues: number
  teams: number
  h2hPairs: number
  shards: number
  shardOf: string
  files: {
    'model.json': number
    'venues.json': number
    'h2h.json': number
    'teams.json': number
    'players/*.json': number
    maxPlayerShard: number
    total: number
  }
}

// ---------------------------------------------------------------------------------------------
// Helpers mirroring the build exactly
// ---------------------------------------------------------------------------------------------
export const HIST_SHARDS = 128
export const playerShard = (cricinfoId: string | number): number => Number(cricinfoId) % HIST_SHARDS

const clip = (x: number, lo: number, hi: number) => (x < lo ? lo : x > hi ? hi : x)

/** Chase features after a legal ball. limit = ball limit of the chase (DLS-revised overs * 6 if known). */
export function chaseFeatures(target: number, score: number, balls: number, wkts: number, limit: number): number[] {
  const runsNeeded = Math.max(target - score, 0)
  const ballsLeft = Math.max(limit - balls, 0)
  const wih = Math.max(10 - wkts, 0)
  const rrr = ballsLeft > 0 ? clip((runsNeeded * 6) / ballsLeft, 0, 36) : runsNeeded > 0 ? 36 : 0
  const crr = balls > 0 ? clip((score * 6) / balls, 0, 36) : 0
  const blf = clip(ballsLeft / limit, 0, 1)
  const rnf = clip(runsNeeded / target, 0, 1)
  const lrw = Math.log1p(runsNeeded / Math.max(wih, 0.5))
  return [rrr, crr, wih, blf, rnf, rrr * blf, wih * blf, lrw]
}

/** Linear interpolation of a par-by-over array at a ball count. */
export function parAt(par: number[], balls: number): number {
  const ov = balls / 6
  const lo = Math.min(Math.floor(ov), par.length - 1)
  const hi = Math.min(lo + 1, par.length - 1)
  return par[lo] + (par[hi] - par[lo]) * (ov - lo)
}

/** First-innings features. limit = 120 (T20) / 300 (ODI); par = venue parByOver (if parN >= 5) else model.first.parGlobal. */
export function firstFeatures(score: number, balls: number, wkts: number, limit: number, par: number[]): number[] {
  const blf = clip((limit - balls) / limit, 0, 1)
  const crr = balls > 0 ? clip((score * 6) / balls, 0, 36) : 0
  return [score, wkts, blf, crr, score - parAt(par, balls), wkts * blf]
}

export function predictLogistic(m: Pick<LogisticModel, 'mean' | 'std' | 'coef' | 'intercept'>, x: number[]): number {
  let eta = m.intercept
  for (let i = 0; i < m.coef.length; i++) eta += m.coef[i] * ((x[i] - m.mean[i]) / m.std[i])
  return 1 / (1 + Math.exp(-eta))
}

/** Normalised venue key, identical to the build. Pass the city to resolve generic names (e.g. "County Ground"). */
export function histVenueKey(venue: string, city: string | undefined, file: Pick<HistVenuesFile, 'venueAliases' | 'ambiguousBaseKeys' | 'cityAliases'>): string {
  const norm = (s: string) =>
    s
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/['‘’`]/g, '')
      .replace(/&/g, ' and ')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim()
      .replace(/\s+/g, ' ')
      .replace(/\b([a-z]) (?=[a-z]\b)/g, '$1')
  const raw = norm(venue.split(',')[0])
  const base = file.venueAliases[raw] ?? raw
  if (city && file.ambiguousBaseKeys.includes(base)) {
    const c = norm(city)
    return `${base} ${file.cityAliases[c] ?? c}`
  }
  return base
}
